import os, socket, urllib.error, urllib.request
print('NO_PROXY=' + os.environ.get('NO_PROXY', 'unset'))
class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, *args):
        return None
opener = urllib.request.build_opener(NoRedirect)
def get(url):
    try:
        with opener.open(url, timeout=10) as r:
            return str(r.status)
    except urllib.error.HTTPError as e:
        return str(e.code)
    except OSError as e:
        return 'ERROR ' + str(e)
print('HOST_DIRECT=' + get('http://host.wslc.internal:18890/'))
print('VIA_PROXY=' + get('http://one.one.one.one/cdn-cgi/trace'))
try:
    socket.create_connection(('1.1.1.1', 80), timeout=3).close()
    print('DIRECT=REACHED')
except OSError:
    print('DIRECT=BLOCKED')
